// Parses GitHub issue body markdown generated by contributor_metadata.yml
// Usage: node scripts/parse-issue-metadata.mjs <file-path>

import fs from "node:fs";

export function parseIssueMetadata(markdown) {
  if (typeof markdown !== "string") {
    throw new Error("Parsing failed: Input is not a string.");
  }

  const lines = markdown.split(/\r?\n/);
  const metadata = {};
  
  let currentKey = null;
  let currentValue = [];

  for (const line of lines) {
    if (line.startsWith("### ")) {
      if (currentKey) {
        metadata[currentKey] = currentValue.join("\n").trim();
      }
      currentKey = line.replace("### ", "").trim();
      currentValue = [];
    } else if (currentKey) {
      if (line.trim() !== "_No response_" && line.trim() !== "") {
        currentValue.push(line);
      }
    }
  }
  
  if (currentKey) {
    metadata[currentKey] = currentValue.join("\n").trim();
  }

  // Validate required fields explicitly
  const requiredFields = ["GitHub Handle", "Stellar Wallet Address", "Primary Role"];
  for (const field of requiredFields) {
    if (!metadata[field] || metadata[field] === "") {
      throw new Error("Parsing failed: Missing required metadata field.");
    }
  }

  const wallet = metadata["Stellar Wallet Address"];
  if (!wallet.startsWith("G") || wallet.length !== 56 || !/^[A-Z0-9]+$/.test(wallet)) {
    throw new Error("Parsing failed: Malformed input for wallet address.");
  }

  const handle = metadata["GitHub Handle"];
  if (handle.includes("@") || handle.includes(" ")) {
     throw new Error("Parsing failed: Malformed input for GitHub handle.");
  }

  const role = metadata["Primary Role"];
  const validRoles = ["Developer", "Reviewer", "Documentation", "Design"];
  if (!validRoles.includes(role)) {
    throw new Error("Parsing failed: Invalid role selected.");
  }

  // Ensure there's no unexpected extra fields that might contain sensitive data
  // Fails closed on ambiguous/extra fields
  const parsedKeys = Object.keys(metadata);
  if (parsedKeys.length !== requiredFields.length) {
    throw new Error("Parsing failed: Ambiguous inputs or unrecognized fields present.");
  }

  return {
    githubHandle: handle,
    stellarWallet: wallet,
    primaryRole: role
  };
}

export function main(args) {
  if (args.length < 1) {
    console.error("Error: Execution failed: Missing file argument.");
    process.exit(1);
  }

  const filePath = args[0];
  let content;
  try {
    content = fs.readFileSync(filePath, "utf8");
  } catch (err) {
    console.error("Error: Execution failed: Cannot read the specified file.");
    process.exit(1);
  }

  try {
    const data = parseIssueMetadata(content);
    console.log(JSON.stringify(data, null, 2));
  } catch (err) {
    if (err.message.startsWith("Parsing failed:")) {
       console.error(err.message);
    } else {
       console.error("Error: Execution failed: An unexpected error occurred during parsing.");
    }
    process.exit(1);
  }
}

// Execute if run directly
import { fileURLToPath } from 'url';
if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main(process.argv.slice(2));
}
